components.css:
.ds-mobile-nav {
    position: fixed;
    bottom: calc(12px + var(--tempo-safe-bottom,env(safe-area-inset-bottom,0px)));
    inset-inline-start: var(--tempo-safe-left,env(safe-area-inset-left,0px));
    inset-inline-end: var(--tempo-safe-right,env(safe-area-inset-right,0px));
    width: min(
      400px,
      calc(100% - 24px - var(--tempo-safe-left,env(safe-area-inset-left,0px)) - var(--tempo-safe-right,env(safe-area-inset-right,0px)))
    );
    margin-inline: auto;
    height: 64px;
    z-index: 101;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    padding: 5px;
    border-radius: 32px;
    border: 1px solid var(--mantine-color-default-border,#ced4da);
    background: var(--mantine-color-body,#fff);
    box-shadow: 0 8px 28px rgb(0 0 0 / 16%);
  }
.ds-tab {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    border-radius: 27px;
    font-size: 11px;
    line-height: 1.2;
    font-weight: 600;
    color: var(--mantine-color-text,#000);
  }
.ds-tab[data-active] {
    background: var(--mantine-color-teal-light,rgba(18,184,134,.1));
    color: var(--mantine-color-teal-light-color,#099268);
  }
.ds-tab:hover {
    background: var(--mantine-color-default-hover,#f8f9fa);
  }
.ds-mobile-nav{font-family:Arial,system-ui,sans-serif}.ds-tab{text-decoration:none}.ds-tab:focus-visible{outline:2px solid var(--mantine-primary-color-filled,#12b886);outline-offset:3px}
@supports (backdrop-filter: blur(20px)) {
    .ds-mobile-nav {
      background: color-mix(
        in srgb,
        var(--mantine-color-body,#fff) 92%,
        transparent
      );
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
    }
  }
